create table if not exists public.learning_events(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete cascade, event_type text not null check(event_type in ('view','search','save','complete','rate','ask','share','follow')), object_type text, object_id text, value numeric, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists learning_events_user_time_idx on public.learning_events(user_id,created_at desc); create index if not exists learning_events_object_idx on public.learning_events(object_type,object_id);
create table if not exists public.social_edges(id uuid primary key default gen_random_uuid(), follower_id uuid not null references auth.users(id) on delete cascade, followed_id uuid not null references auth.users(id) on delete cascade, relation text not null default 'follow' check(relation in ('follow','study_group','teacher')), created_at timestamptz not null default now(), unique(follower_id,followed_id,relation), check(follower_id<>followed_id));
create table if not exists public.recommendation_items(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, object_type text not null, object_id text not null, score numeric not null default 0, reason jsonb not null default '{}'::jsonb, algorithm_version text not null default 'hybrid-v1', expires_at timestamptz, created_at timestamptz not null default now(), unique(user_id,object_type,object_id));
alter table public.learning_events enable row level security; alter table public.social_edges enable row level security; alter table public.recommendation_items enable row level security;
create policy learning_events_owner on public.learning_events for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy social_edges_participant on public.social_edges for all using(follower_id=auth.uid() or followed_id=auth.uid()) with check(follower_id=auth.uid()); create policy recommendations_owner on public.recommendation_items for all using(user_id=auth.uid()) with check(user_id=auth.uid());
